let lang=localStorage.getItem('zhu-team-language')==='en'?'en':'zh';
const page=document.body.dataset.page, itemId=document.body.dataset.id,main=document.getElementById('main');
const cms=window.SITE_CMS;
if(cms){profiles.splice(0,profiles.length,...cms.faculty);staff.splice(0,staff.length,...cms.staff);newsItems.splice(0,newsItems.length,...cms.news);breakthroughs.splice(0,breakthroughs.length,...cms.results);teamAwards.splice(0,teamAwards.length,...cms.awards);teamOverview.splice(0,teamOverview.length,...cms.overview);}
function metric(id,fallback){const m=cms?.metrics.find(m=>m.id===id);return escapeHtml(m?.value??fallback);}
function metricLabel(id,zh,en){const m=cms?.metrics.find(m=>m.id===id);return m?copy(m.label):t(zh,en);}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const t=(zh,en)=>lang==='zh'?zh:en;
const copy=v=>escapeHtml(typeof v==='string'?v:v?.[lang]);
const pageNames={publications:['论文与著作','Papers & books'],home:['首页','Home'],about:['团队概况','About'],research:['科研方向','Research'],news:['新闻动态','News'],people:['导师','Faculty'],students:['学生','Students'],staff:['实验室工作人员','Laboratory staff'],alumni:['毕业生','Alumni'],results:['科研成果','Research achievements'],awards:['科研奖项','Awards'],platforms:['实验平台','Facilities'],contact:['联系与加入','Contact & join']};
function titleBlock(kicker,zh,en,desc=''){return `<section class="page-heading section"><div class="breadcrumbs"><a href="index.html">${t('首页','Home')}</a><span>/</span><span>${t(zh,en)}</span></div><p class="eyebrow dark">${kicker}</p><h1>${t(zh,en)}</h1>${desc?`<p class="page-description">${desc}</p>`:''}</section>`;}
function heading(kicker,zh,en,href,label){return `<div class="section-heading"><div><p class="eyebrow dark">${kicker}</p><h2>${t(zh,en)}</h2></div>${href?`<a class="text-link" href="${href}">${label}</a>`:''}</div>`;}
function figure(file,zh,en){return `<figure class="evidence-figure"><button class="image-expand" data-image="${file}" data-caption="${escapeHtml(t(zh,en))}" aria-label="${t('放大图片：','Enlarge image: ')}${escapeHtml(t(zh,en))}"><img src="assets/${file}" alt="${escapeHtml(t(zh,en))}" loading="lazy"><span>${t('放大查看','Enlarge')}</span></button><figcaption>${t(zh,en)}</figcaption></figure>`;}
function list(items,ordered=true){return `<${ordered?'ol':'ul'} class="cv-list">${items.map(v=>`<li>${v.url?`<a href="${escapeHtml(v.url)}" target="_blank" rel="noopener">${copy(v)}</a>`:copy(v)}</li>`).join('')}</${ordered?'ol':'ul'}>`;}
function newsCards(limit=Infinity){if(!newsItems.length)return `<p class="content-empty">${t('暂无新闻','No news published yet.')}</p>`;return `<div class="news-grid">${newsItems.slice(0,limit).map(n=>`<a href="news-${n.id}.html" class="news-card"><div class="news-photo"><img src="${n.image}" alt="${copy(n.title)}" loading="lazy"></div><div class="news-card-copy"><p class="news-meta"><span>${copy(n.kind)}</span><time datetime="${n.date}">${n.date}</time></p><h3>${copy(n.title)}</h3><p>${copy(n.summary)}</p><span class="text-link">${t('阅读新闻','Read story')}</span></div></a>`).join('')}</div>`;}
function renderHome(){return `<section class="home-hero"><div class="home-hero-copy"><a class="home-lab-link" href="https://sklam.ustb.edu.cn/" target="_blank" rel="noopener" aria-label="${t("访问绿色低碳钢铁冶金全国重点实验室官网","Visit the National Key Laboratory of Green and Low-Carbon Iron and Steel Metallurgy")}"><img src="assets/lab-official-logo.png" width="704" height="80" alt="绿色低碳钢铁冶金全国重点实验室"><span>${t("实验室官网","Laboratory website")}</span></a><h1>${t('以冶金创新，<br>迈向绿色未来。','Metallurgical innovation.<br>A greener future.')}</h1><p class="home-hero-description">${t('朱荣院士领衔，深耕绿色低碳炼钢与喷射冶金，连接科学发现与工业实践。','Led by Academician Rong Zhu, advancing green steelmaking and jet metallurgy from discovery to industrial practice.')}</p><a class="button" href="profile-zhu.html"><span>${t('认识朱荣院士','Meet Academician Zhu')}</span><span></span></a><a class="hero-secondary" href="research.html">${t('探索科研方向','Explore our research')}</a></div><div class="home-portrait"><img src="${profiles.find(p=>p.id==='zhu')?.photo||'assets/zhu-rong.jpg'}" alt="${t('朱荣院士','Academician Rong Zhu')}"><div class="portrait-caption"><strong>${t('朱荣','Rong Zhu')}</strong><span>${t('中国工程院院士 · 北京科技大学终身教授','Academician, Chinese Academy of Engineering · USTB')}</span></div></div></section>
<section class="home-numbers"><div><strong>${metric('enterprises','200+')}</strong><p>${metricLabel('enterprises','钢铁企业推广应用','Steel enterprises reached')}</p></div><div><strong>${metric('papers','210+')}</strong><p>${metricLabel('papers','发表学术论文','Published papers')}</p></div><div><strong>${metric('national-awards','4')}</strong><p>${metricLabel('national-awards','国家科技进步二等奖','State S&T Progress Second Prizes')}</p></div><a href="about.html">${t('了解我们的团队','Discover our team')}</a></section>
<section class="section home-news">${heading('LATEST NEWS','新闻动态','Latest news','news.html',t('全部新闻','All news'))}${newsCards(2)}</section>
<section class="section home-research">${heading('RESEARCH AREAS','探索六大科研方向','Explore our research','research.html',t('研究总览','Research overview'))}<div class="research-shortcuts research-visual-grid">${researchGroups.map((g,i)=>`<a href="research-${g.id}.html" class="research-visual-card" style="--reveal-delay:${i%3*90}ms"><img src="assets/research-${g.id}-photo.jpg" alt="" loading="lazy" width="520" height="340"><div class="research-visual-copy"><h3>${copy(g.title)}</h3><p>${copy(g.intro)}</p><span>${t('浏览研究方向','Explore this research')}</span></div></a>`).join('')}</div></section>
<section class="home-team section"><img src="assets/team.jpg" alt="${t('团队合影','Our team')}" loading="lazy"><div><p class="eyebrow dark">PEOPLE BEHIND THE SCIENCE</p><h2>${t('集智创新，<br>鼎力实践。','Shared ideas.<br>Practical impact.')}</h2><p>${t('认识我们的导师、学生和实验室工作人员，与团队一道探索绿色钢铁的更多可能。','Meet our faculty, students and laboratory staff, and explore the possibilities of greener steel.')}</p><a class="text-link" href="people.html">${t('走近团队','Meet our people')}</a></div></section>`;}
function renderAbout(){return titleBlock('OUR TEAM','团队概况','Team overview',t('厚德立人 · 集智创新 · 鼎力实践','Integrity · Collective innovation · Dedicated practice'))+`<section class="section page-body"><div class="overview-grid"><div class="overview-text">${teamOverview.map(p=>`<p>${copy(p)}</p>`).join('')}</div><figure class="team-photo"><img src="assets/team.jpg" alt="${t('团队合影','Team photograph')}"><figcaption>${t('绿色低碳炼钢团队 · 北京科技大学','Green & Low-Carbon Steelmaking Team · USTB')}</figcaption></figure></div><div class="about-center"><p class="eyebrow dark">METALLURGICAL LANCE RESEARCH CENTER</p><h2>${t('北京科技大学冶金喷枪研究中心','Metallurgical Lance Research Center, USTB')}</h2><p>${t('团队坚持喷射冶金特色，围绕超音速供气、底吹、喷粉及燃烧技术，促进钢铁碳中和、优特钢冶炼、智能检测控制与资源综合利用协同发展。','With a distinctive focus on jet metallurgy, the team develops supersonic gas supply, bottom blowing, powder injection and combustion technologies to advance carbon neutrality, special steel production, intelligent monitoring and resource utilization.')}</p></div><div class="organization"><h3>${t('组织与科研依托','Research organizations')}</h3>${list(organizations,false)}</div><div class="related-links"><a href="people.html">${t('人员队伍','People')}</a><a href="platforms.html">${t('实验平台','Facilities')}</a><a href="contact.html">${t('联系与加入','Connect')}</a></div></section>`;}
function researchSubnav(){return `<nav class="subnav" aria-label="${t('科学研究栏目','Research sections')}"><a href="research.html" ${page.includes('research')?'aria-current="page"':''}>${t('科研方向','Research areas')}</a><a href="publications.html" ${page==='publications'?'aria-current="page"':''}>${t('论文与著作','Papers & books')}</a><a href="results.html" ${page==='results'?'aria-current="page"':''}>${t('科研成果','Achievements')}</a><a href="awards.html" ${page==='awards'?'aria-current="page"':''}>${t('科研奖项','Awards')}</a><a href="platforms.html" ${page==='platforms'?'aria-current="page"':''}>${t('实验平台','Facilities')}</a></nav>`;}
function renderResearch(){return titleBlock('OUR RESEARCH','科研方向','Research areas',t('以喷射冶金为特色，连接基础研究、工艺创新与工程应用。','Connecting fundamental science, process innovation and engineering through jet metallurgy.'))+researchSubnav()+`<section class="section page-body"><div class="research-directory">${researchGroups.map((g,i)=>`<a href="research-${g.id}.html" class="research-directory-card"><span class="directory-index">0${i+1}</span><h2>${copy(g.title)}</h2><p>${copy(g.intro)}</p><ul>${g.topics.map(s=>`<li>${escapeHtml(s[lang==='zh'?0:1])}</li>`).join('')}</ul><span class="text-link">${t('进入研究方向','Explore this area')}</span></a>`).join('')}</div></section>`;}
function renderResearchDetail(){const g=researchGroups.find(g=>g.id===itemId);return titleBlock('RESEARCH AREA',g.title.zh,g.title.en,copy(g.intro))+researchSubnav()+`<section class="section page-body research-detail-layout"><aside class="research-sidebar"><h2>${t('科研方向','Research areas')}</h2>${researchGroups.map(x=>`<a href="research-${x.id}.html" ${g.id===x.id?'aria-current="page"':''}>${copy(x.title)} <span></span></a>`).join('')}</aside><div><div class="research-topic-header"><h2>${t('研究子方向','Research topics')}</h2><p>${t('从具体工艺与技术问题出发，探索绿色冶金新路径。','Exploring greener metallurgy through specific process and technology questions.')}</p></div>${g.topics.map((s,i)=>`<details class="research-topic" open><summary><span>0${i+1}</span><h3>${escapeHtml(s[lang==='zh'?0:1])}</h3><b>−</b></summary><p>${escapeHtml(s[lang==='zh'?2:3])}</p></details>`).join('')}<figure class="research-source-figure"><img src="${g.image}" alt="${copy(g.title)}" loading="lazy"><figcaption>${t('研究方向图示 · 2026年9月团队介绍','Research illustrations · September 2026 team introduction')}</figcaption></figure><div class="related-links"><a href="publications.html?theme=${g.id}">${t('相关论文','Related publications')}</a><a href="results.html">${t('相关科研成果','Research achievements')}</a><a href="platforms.html">${t('实验平台','Facilities')}</a></div></div></section>`;}
function peopleNav(){const cats=[['people','导师','Faculty'],['students','学生','Students'],['staff','实验室工作人员','Laboratory staff'],['alumni','毕业生','Alumni']];return `<nav class="subnav people-subnav" aria-label="${t('人员分区','People categories')}">${cats.map(([id,zh,en])=>`<a href="${id}.html" ${(page===id||page==='profile'&&id==='people')?'aria-current="page"':''}>${t(zh,en)}</a>`).join('')}</nav>`;}
function renderProfile(){const p=profiles.find(p=>p.id===itemId),sections=[['代表性论文与著作','Selected papers & books',p.papers],['代表性专利','Selected patents',p.patents],['科研项目','Research projects',p.projects],['荣誉与奖励','Honors & awards',p.awards]];return titleBlock('FACULTY PROFILE',p.name.zh,p.name.en)+peopleNav()+`<section class="section page-body profile-layout refreshed-profile"><aside class="profile-photo-column"><img src="${p.photo}" alt="${copy(p.name)}" class="profile-large-photo"><p>${copy(p.role)}</p><div class="profile-websites">${facultyWebLinks(p)}</div><a href="people.html" class="text-link"> ${t('返回导师队伍','Back to faculty')}</a></aside><article class="profile-cv">${p.phone||p.email||p.office?.zh?`<section class="profile-contact" aria-label="${t('联系方式','Contact information')}"><h2>${t('联系方式','Contact')}</h2><dl>${p.phone?`<div><dt>${t('电话','Phone')}</dt><dd><a href="tel:${escapeHtml(p.phone.replace(/[^+0-9]/g,''))}">${escapeHtml(p.phone)}</a></dd></div>`:''}${p.email?`<div><dt>${t('邮箱','Email')}</dt><dd><a href="mailto:${escapeHtml(p.email)}">${escapeHtml(p.email)}</a></dd></div>`:''}${p.office?.zh?`<div><dt>${t('办公地点','Office')}</dt><dd>${copy(p.office)}</dd></div>`:''}</dl></section>`:''}${p.intro.zh?`<section class="cv-section profile-introduction"><h2>${t('个人简介','Biography')}</h2>${p.affiliation?.zh?`<p class="cv-affiliation">${copy(p.affiliation)}</p>`:''}<p class="cv-intro">${copy(p.intro)}</p></section>`:''}${p.fields.length?`<section class="cv-section"><h3>${t('研究领域','Research interests')}</h3>${list(p.fields,false)}${p.students?.zh?`<p class="profile-discipline"><strong>${t('招生专业：','Postgraduate disciplines: ')}</strong>${copy(p.students)}</p>`:''}</section>`:''}${p.experience.length?`<section class="cv-section"><h3>${t('教育与工作经历','Education & appointments')}</h3>${list(p.experience,false)}</section>`:''}${sections.filter(x=>x[2]?.length).map(([zh,en,items])=>`<section class="cv-section"><h3>${t(zh,en)}</h3>${list(items)}</section>`).join('')}${p.websites?.length?`<section class="profile-official-sources"><h3>${t('官方个人主页','Official faculty pages')}</h3>${facultyWebLinks(p)}</section>`:''}</article></section>`;}
function renderNews(){return titleBlock('NEWS & STORIES','新闻动态','News & stories',t('关注团队进展、媒体报道与科研荣誉。','Research progress, media coverage and recognition.'))+`<section class="section page-body">${newsCards()}</section>`;}
function renderArticle(){const n=newsItems.find(n=>n.id===itemId);return `<section class="article-header section"><div class="breadcrumbs"><a href="news.html">${t('新闻动态','News')}</a><span>/</span><span>${copy(n.kind)}</span></div><p class="eyebrow dark">${copy(n.kind)}</p><h1>${copy(n.title)}</h1><p class="article-meta"><time datetime="${n.date}">${n.date}</time><span>${copy(n.source)}</span></p></section><article class="news-article section"><img src="${n.image}" class="article-cover" alt="${copy(n.title)}"><p class="article-lead">${copy(n.summary)}</p>${n.paragraphs.map(p=>`<p>${copy(p)}</p>`).join('')}<p class="article-source-note">${t('根据所提供的原始报道截图整理，发布日期保留原文记录。','Adapted from the supplied original report screenshot; publication date follows the source.')}</p>${n.screenshot?`<details class="source-screenshot"><summary>${t('查看原始报道截图','View the original report screenshot')}</summary><img src="${n.screenshot}" alt="${t('原始报道长截图','Original report screenshot')}" loading="lazy"></details>`:''}<a class="text-link" href="news.html"> ${t('返回新闻列表','Back to news')}</a></article>`;}
function renderResults(){const metrics=(cms?.metrics||[]).filter(m=>m.id!=='national-awards').map(m=>[escapeHtml(m.value),copy(m.label)]);return titleBlock('RESEARCH & IMPACT','科研成果','Research achievements')+researchSubnav()+`<section class="section page-body"><div class="metrics-grid">${metrics.map(m=>`<div><strong>${m[0]}</strong><span>${m[1]}</span></div>`).join('')}</div><div class="breakthroughs">${breakthroughs.map((b,i)=>`<article class="breakthrough"><div class="breakthrough-index">0${i+1}</div><div><h2>${copy(b.title)}</h2>${b.image?`<img class="managed-result-image" src="${b.image}" alt="${copy(b.title)}" loading="lazy">`:''}<p>${copy(b.body)}</p><span class="result-metric">${copy(b.metric)}</span></div></article>`).join('')}</div>${figure('projects.png','近年来承担的项目及企业合作情况','Recent projects and industry collaborations')}</section>`;}
function renderAwards(){return titleBlock('RECOGNITION','科研奖项','Awards & recognition')+researchSubnav()+`<section class="section page-body"><div class="awards-lead"><strong>${metric('national-awards','4')}<span>${t('项','awards')}</span></strong><div><h2>${t('国家科技进步二等奖','State Science and Technology Progress Award · Second Prize')}</h2><p>${t('三项排名第一','Ranked first in three award-winning achievements')}</p></div></div><p class="awards-summary">${t('团队还获得何梁何利科学与技术进步奖、全国创新争先奖、省部级特等奖1项、一等奖8项。','Further honors include the Ho Leung Ho Lee Science and Technology Progress Award, the National Innovation Award, one provincial or ministerial Special Prize and eight First Prizes.')}</p><ol class="award-list">${teamAwards.map((a,i)=>`<li><span>0${i+1}</span><p>${copy(a)}</p></li>`).join('')}</ol>${figure('awards.png','近年来团队获得奖项','Recent awards received by the team')}<div class="related-links"><a href="news-gold-award.html">${t('2026年全国发明展览会金奖报道','2026 National Invention Exhibition Gold Award story')}</a></div></section>`;}
function renderPlatforms(){return titleBlock('RESEARCH FACILITIES','实验平台','Research facilities',t('连接实验室研究、中试验证与工业实践。','Connecting laboratory research, pilot validation and industrial practice.'))+researchSubnav()+`<section class="section page-body">${platforms.map(p=>`<article class="platform-article"><p class="eyebrow dark">${copy(p.location)}</p><h2>${copy(p.title)}</h2><p>${copy(p.body)}</p><img src="${p.image}" alt="${copy(p.title)}" loading="lazy"></article>`).join('')}</section>`;}
function renderContact(){return titleBlock('CONNECT WITH US','联系与加入','Contact & join')+`<section class="section page-body contact-grid"><div><h2>${t('共同探索绿色钢铁的未来','Explore the future of greener steel')}</h2><p>${t('欢迎开展学术交流、产学研合作与研究生培养方面的联系。','We welcome academic exchange, university–industry collaboration and inquiries about postgraduate study.')}</p><h3>${t('研究生专业方向','Postgraduate disciplines')}</h3><p>${t('冶金工程；部分导师招收材料科学与工程方向学生。','Metallurgical Engineering; Materials Science and Engineering is also offered by selected supervisors.')}</p><a class="text-link" href="people.html">${t('查看导师及研究领域','Explore faculty research interests')}</a></div><div class="contact-card"><p class="eyebrow dark">CONTACT</p><h3>${t('朱荣老师','Prof. Rong Zhu')}</h3><a href="mailto:zhurong1201@126.com">zhurong1201@126.com</a><p>${t('北京科技大学 · 北京','University of Science and Technology Beijing · Beijing')}</p></div></section>`;}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-zh][data-en]').forEach(el=>el.innerHTML=el.dataset[lang]);document.getElementById('language').innerHTML=lang==='zh'?'EN <span></span>':'中文 <span></span>';document.getElementById('language').setAttribute('aria-label',lang==='zh'?'Switch language to English':'切换为中文');
const views={home:renderHome,about:renderAbout,research:renderResearch,'research-detail':renderResearchDetail,publications:renderPublicationExplorer,people:renderPeopleDirectory,students:renderPeopleDirectory,staff:renderPeopleDirectory,alumni:renderPeopleDirectory,profile:renderProfile,news:renderNews,article:renderArticle,results:renderResults,awards:renderAwards,platforms:renderPlatforms,contact:renderContact};main.innerHTML=views[page]();bindExplorer();bindResearchMotion();let label=pageNames[page]?.[lang==='zh'?0:1]||(page==='profile'?profiles.find(p=>p.id===itemId).name[lang]:page==='article'?newsItems.find(n=>n.id===itemId).title[lang]:researchGroups.find(g=>g.id===itemId).title[lang]);document.title=label+' · '+t('朱荣院士团队','Zhu Rong Group');
const active=page==='home'?'index':page==='profile'||['students','staff','alumni'].includes(page)?'people':page==='research-detail'||page==='platforms'?'research':page==='article'?'news':page;document.querySelectorAll('#navigation a').forEach(a=>{if(a.getAttribute('href')===active+'.html')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
const menu=document.getElementById('menu'),nav=document.getElementById('navigation');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'×':'☰';});
document.getElementById('language').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('zhu-team-language',lang);render();});
const imageDialog=document.createElement('dialog');imageDialog.className='image-dialog';imageDialog.setAttribute('aria-label','图片预览 / Image preview');imageDialog.innerHTML='<button class="close" aria-label="关闭 / Close">×</button><img alt=""><p></p>';document.body.append(imageDialog);imageDialog.querySelector('.close').addEventListener('click',()=>imageDialog.close());imageDialog.addEventListener('click',e=>{if(e.target===imageDialog){const r=imageDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)imageDialog.close();}});document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(!b)return;imageDialog.querySelector('img').src='assets/'+b.dataset.image;imageDialog.querySelector('img').alt=b.dataset.caption;imageDialog.querySelector('p').textContent=b.dataset.caption;imageDialog.showModal();});
const legacy={people:'people',research:'research',about:'about',impact:'results',awards:'awards',news:'news',contact:'contact',focus:'research'};if(page==='home'&&legacy[location.hash.slice(1)])location.replace(legacy[location.hash.slice(1)]+'.html');else render();
